import { ExtensionsSection } from "./components/extensions-section";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { HowItWorks } from "./components/how-it-works";
import { LandingHeader } from "./components/landing-header";
import { LandingHero } from "./components/landing-hero";
import { LandingPricing } from "./components/landing-pricing";
import { LandingStats } from "./components/landing-stats";
import { WhySaveIt } from "./components/why-saveit";

export function App() {
  return (
    <div className="landing-page min-h-screen">
      <LandingHeader />
      <main>
        <LandingHero />
        <LandingStats />
        <WhySaveIt />
        <HowItWorks />
        <ExtensionsSection />
        <LandingPricing />
        <FAQ />
      </main>
      <Footer />
    </div>
  );
}

import tailwindcss from "@tailwindcss/vite";
import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [react(), tailwindcss()],
  server: {
    host: "127.0.0.1",
    strictPort: true,
  },
});

@import "tailwindcss";
@import "@fontsource-variable/geist";

@source "./**/*.{ts,tsx}";

:root {
  font-family: "Geist Variable", sans-serif;
  color: #fafafa;
  background: #141414;
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  --font-elegant: Georgia, "Times New Roman", serif;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: #141414;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

.font-elegant {
  font-family: var(--font-elegant);
}

.landing-page {
  position: relative;
  overflow: hidden;
  background: #141414;
  color: #fafafa;
}

.landing-page::before {
  position: fixed;
  z-index: 0;
  inset: 0;
  pointer-events: none;
  content: "";
  opacity: 0.04;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 256px 256px;
}

.landing-page > * {
  position: relative;
  z-index: 1;
}

const faqs = [
  {
    question: 'What does "agentic" mean?',
    answer:
      "Agentic AI doesn't just respond - it acts autonomously. While most AI tools wait for you to give commands, agentic systems make decisions and take action on their own. Your SaveIt agent automatically organizes your bookmarks, learns your patterns, and retrieves content before you even search.",
  },
  {
    question: "Can I cancel any time?",
    answer:
      "Yes. Manage or cancel from the billing provider you used. Pro stays active until the end of your current billing period.",
  },
  {
    question: "Do I have a limit?",
    answer:
      "Free includes up to 20 bookmarks, 20 AI bookmark runs, and 10 chat questions each month. Pro includes up to 50,000 bookmarks, 1,500 AI runs, and 200 chat questions each month.",
  },
  {
    question: "How to upgrade my plan?",
    answer:
      "Choose Upgrade to Pro during setup or from the pricing page, sign in to the account you want to upgrade, then complete the secure checkout.",
  },
  {
    question: "Is my data sent to any server?",
    answer:
      "Yes, your bookmarks are stored on our servers so you can access them from any device. We use encryption and never share your data with third parties.",
  },
  {
    question: "Do you offer refunds?",
    answer:
      "Yes, we offer a 7-day refund guarantee. Just contact hi@saveit.now and get an instant refund. No questions asked.",
  },
];

export const FAQ = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <h2 className="font-elegant text-4xl tracking-tight text-[#fafafa] md:text-5xl">
        Questions <em>& answers</em>
      </h2>

      <div className="mt-12 grid gap-x-16 gap-y-10 md:grid-cols-2">
        {faqs.map((faq) => (
          <div key={faq.question}>
            <h3 className="text-[15px] font-medium text-[#fafafa]">
              {faq.question}
            </h3>
            <p className="mt-3 text-sm leading-relaxed text-[#888]">
              {faq.answer}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

import { CheckIcon } from "lucide-react";

const tiers = [
  {
    name: "Free",
    id: "tier-free",
    href: "/signin?intent=signup",
    priceMonthly: "$0",
    description:
      "Perfect for getting started with bookmarking and organizing your digital content.",
    features: [
      "20 bookmarks",
      "Chrome extension",
    ],
    featured: false,
  },
  {
    name: "Pro",
    id: "tier-pro",
    href: "/upgrade",
    priceMonthly: "$5",
    description:
      "Everything you need to organize your digital knowledge with advanced features.",
    features: [
      "Up to 50,000 bookmarks",
      "API Access",
      "Export to CSV",
      "Priority support",
    ],
    featured: true,
  },
];

export const LandingPricing = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <p className="text-sm text-[#666] mb-4">007 - Pricing</p>

      <div>
        <h2 className="font-elegant text-4xl md:text-5xl tracking-tight text-[#fafafa]">
          Choose the right plan <em>for you</em>
        </h2>
      </div>

      <p className="mt-6 max-w-2xl text-base text-[#888]">
        Start for free, upgrade when you need more. No hidden fees, just great
        features for organizing your digital knowledge.
      </p>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-px rounded-xl border border-[#2a2a2a] overflow-hidden mt-16">
        {tiers.map((tier, tierIdx) => (
          <div
            key={tier.id}
            className={`bg-[#1a1a1a] p-8 ${tierIdx === 0 && !tier.featured ? "lg:border-r border-[#2a2a2a]" : ""}`}
          >
            <h3 id={tier.id} className="text-base font-medium text-[#fafafa]">
              {tier.name}
            </h3>

            <p className="mt-4 flex items-baseline gap-x-2">
              <span className="text-5xl font-semibold tracking-tight text-[#fafafa]">
                {tier.priceMonthly}
              </span>
              <span className="text-[#666]">/month</span>
            </p>
            {tier.featured ? (
              <p className="mt-2 text-xs text-[#666]">Billed annually</p>
            ) : null}

            <p className="mt-6 text-base text-[#888]">{tier.description}</p>

            <ul
              role="list"
              className="mt-8 space-y-3 text-sm text-[#888] sm:mt-10"
            >
              {tier.features.map((feature) => (
                <li key={feature} className="flex gap-x-3">
                  <CheckIcon
                    aria-hidden="true"
                    className="h-6 w-5 flex-none text-[#fafafa]"
                  />
                  {feature}
                </li>
              ))}
            </ul>

            <a
              href={tier.href}
              aria-describedby={tier.id}
              className={`mt-8 inline-flex h-10 items-center justify-center rounded-full px-6 text-sm font-medium w-full text-center transition-colors ${
                tier.featured
                  ? "bg-[#fafafa] text-[#141414] hover:bg-[#e0e0e0]"
                  : "border border-white/10 text-[#fafafa] hover:bg-white/5"
              }`}
            >
              {tier.featured ? "Upgrade to Pro" : "Get Started Free"}
            </a>
          </div>
        ))}
      </div>
    </section>
  );
};

const steps = [
  {
    number: 1,
    title: "Sign up free",
    description:
      "Create your account in seconds. No credit card needed. Start with 20 free bookmarks.",
  },
  {
    number: 2,
    title: "Install the extension",
    description:
      "Add our Chrome or Firefox extension. Pin it to your toolbar for one-click saving.",
  },
  {
    number: 3,
    title: "Save anything",
    description:
      "Click the extension on any website, YouTube video, tweet, or PDF to save it instantly.",
  },
  {
    number: 4,
    title: "Ask your agent",
    description:
      "Describe what you're looking for in natural language. Your agent finds it instantly.",
  },
];

export const HowItWorks = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <p className="text-sm text-[#666]">How it works</p>
      <h2 className="mt-3 font-elegant text-4xl tracking-tight text-[#fafafa] md:text-5xl">
        Up and running <em>in under a minute.</em>
      </h2>
      <p className="mt-4 max-w-xl text-base text-[#888]">
        No complex setup or folders to configure. Create your free account,
        install the extension, and start saving.
      </p>

      <div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
        {steps.map((step) => (
          <div
            key={step.number}
            className="rounded-xl border border-[#2a2a2a] bg-[#1a1a1a] p-6"
          >
            <div className="mb-4 flex size-8 items-center justify-center rounded-full border border-[#2a2a2a] text-sm text-[#888]">
              {step.number}
            </div>
            <h3 className="mb-2 text-[15px] font-medium text-[#fafafa]">
              {step.title}
            </h3>
            <p className="text-sm leading-relaxed text-[#666]">
              {step.description}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

const EXTENSIONS_LINK = "https://saveit.now/extensions";

interface ExtensionFeature {
  id: string;
  gif: string;
  title: string;
  description: string;
}

const extensionFeatures: ExtensionFeature[] = [
  {
    id: "install",
    gif: "/docs/pin-extensions.gif",
    title: "Install Extensions",
    description:
      "Download our browser extension and pin it to your toolbar. Available for Chrome and Firefox, making it accessible with just one click.",
  },
  {
    id: "save-pages",
    gif: "/docs/save-link.gif",
    title: "Save Any Web Page",
    description:
      "Click the extension icon on any website, YouTube video, X post, PDF, or any other page to save it instantly to your collection.",
  },
  {
    id: "save-images",
    gif: "/docs/save-image2.gif",
    title: "Save Images Too",
    description:
      "Right-click on any image and select 'Save Image' to add it to your collection. Perfect for saving visual inspiration and references.",
  },
];

function ExtensionFeatureCard({ feature }: { feature: ExtensionFeature }) {
  return (
    <div className="rounded-xl border border-[#2a2a2a] bg-[#1a1a1a] p-6 flex flex-col gap-6 text-center">
      <div className="flex justify-center">
        <img
          src={feature.gif}
          alt={feature.title}
          className="rounded-lg border border-[#2a2a2a] max-w-full h-auto"
        />
      </div>
      <div className="space-y-2">
        <h3 className="text-[15px] font-medium text-[#fafafa]">{feature.title}</h3>
        <p className="text-sm text-[#666] leading-relaxed">
          {feature.description}
        </p>
      </div>
    </div>
  );
}

export const ExtensionsSection = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28 flex flex-col gap-8">
      <div className="text-center justify-center flex flex-col gap-2 items-center">
        <p className="text-sm text-[#666]">
          006  -  Extensions
        </p>
        <h2 className="font-elegant text-4xl md:text-5xl tracking-tight text-[#fafafa]">One simple <em>click away</em></h2>
        <p className="text-[#888]">Do nothing. Just save it.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 lg:gap-8">
        {extensionFeatures.map((feature) => (
          <ExtensionFeatureCard key={feature.id} feature={feature} />
        ))}
      </div>
      <a href={EXTENSIONS_LINK} className="mx-auto inline-flex h-10 items-center justify-center rounded-full bg-[#fafafa] px-6 text-sm font-medium text-[#141414] hover:bg-[#e0e0e0] transition-colors">Download Extension</a>
    </section>
  );
};

const stats = [
  {
    value: "$5",
    label: "Per month. No hidden fees, no per-bookmark charges. Your data stays yours.",
  },
  {
    value: "4",
    label:
      "Content types supported. YouTube, PDF, tweets, web pages. All indexed automatically.",
  },
  {
    value: "< 1s",
    label:
      "Search latency. Semantic search finds what you need instantly, by meaning.",
  },
];

export const LandingStats = () => {
  return (
    <section className="mx-auto max-w-5xl px-4 py-20 lg:py-28">
      <div className="grid gap-6 md:grid-cols-3">
        {stats.map((stat) => (
          <div
            key={stat.value}
            className="rounded-xl border border-[#2a2a2a] bg-[#1a1a1a] p-6"
          >
            <p className="font-elegant text-4xl tracking-tight text-[#fafafa]">
              {stat.value}
            </p>
            <p className="mt-3 text-sm leading-relaxed text-[#888]">
              {stat.label}
            </p>
          </div>
        ))}
      </div>
    </section>
  );
};

import type { ReactNode } from "react";

type LandingAppButtonProps = {
  authIntent?: "signin" | "signup";
  children?: ReactNode;
  className?: string;
  showAlwaysOpenPrompt?: boolean;
  signedOutChildren?: ReactNode;
  variant?: "default" | "outline";
};

export function LandingAppButton({
  authIntent = "signup",
  children = "Open SaveIt.now",
  className = "",
  signedOutChildren,
  variant = "default",
}: LandingAppButtonProps) {
  const base =
    "inline-flex h-9 items-center justify-center rounded-full px-4 text-sm font-medium transition-colors";
  const appearance =
    variant === "outline"
      ? "border border-white/10 bg-transparent text-[#fafafa] hover:bg-white/5"
      : "bg-[#fafafa] text-[#141414] hover:bg-[#e0e0e0]";

  return (
    <a
      className={`${base} ${appearance} ${className}`}
      href={`/signin?intent=${authIntent}&step=email`}
    >
      {signedOutChildren ?? children}
    </a>
  );
}

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";

import { App } from "./App";
import "./styles.css";

createRoot(document.getElementById("root")!).render(
  <StrictMode>
    <App />
  </StrictMode>,
);

import { ClosingCta } from "./components/closing-cta";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { HowItWorks } from "./components/how-it-works";
import { IosSection } from "./components/ios-section";
import { LandingHeader } from "./components/landing-header";
import { LandingHero } from "./components/landing-hero";
import { LandingPricing } from "./components/landing-pricing";
import { PromiseSection } from "./components/promise-section";

export function App() {
  return (
    <div className="landing-page min-h-screen">
      <LandingHeader />
      <main>
        <LandingHero />
        <HowItWorks />
        <PromiseSection />
        <IosSection />
        <LandingPricing />
        <FAQ />
        <ClosingCta />
      </main>
      <Footer />
    </div>
  );
}

import { AskDemo } from "./components/ask-demo";
import { CaptureStrip } from "./components/capture-strip";
import { ClosingCTA } from "./components/closing-cta";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { Hero } from "./components/hero";
import { IOS } from "./components/ios";
import { Pricing } from "./components/pricing";
import { Promise } from "./components/promise";
import { SiteHeader } from "./components/site-header";
import { Transformation } from "./components/transformation";
import { Workflow } from "./components/workflow";
import { useRevealObserver } from "./lib/motion";

export function App() {
  // One observer drives every [data-reveal] on the page.
  useRevealObserver();

  return (
    <div className="landing-page min-h-screen">
      <a
        href="#workflow"
        className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-[70] focus:rounded-full focus:bg-cream focus:px-5 focus:py-3 focus:text-sm focus:font-medium focus:text-ink"
      >
        Skip to content
      </a>

      <SiteHeader />

      <main>
        <Hero />
        <CaptureStrip />
        <Transformation />
        <Workflow />
        <AskDemo />
        <Promise />
        <IOS />
        <Pricing />
        <FAQ />
        <ClosingCTA />
      </main>

      <Footer />
    </div>
  );
}

import { AgenticWorkflow } from "./components/agentic-workflow";
import { ClosingCta } from "./components/closing-cta";
import { FAQ } from "./components/faq";
import { Footer } from "./components/footer";
import { IosSection } from "./components/ios-section";
import { LandingHeader } from "./components/landing-header";
import { LandingHero } from "./components/landing-hero";
import { LandingPricing } from "./components/landing-pricing";
import { Manifesto } from "./components/manifesto";
import { PromiseSection } from "./components/promise-section";

export function App() {
  return (
    <div className="landing-page min-h-screen">
      <LandingHeader />
      <main>
        <LandingHero />
        <Manifesto />
        <AgenticWorkflow />
        <PromiseSection />
        <IosSection />
        <LandingPricing />
        <FAQ />
        <ClosingCta />
      </main>
      <Footer />
    </div>
  );
}

