@import "tailwindcss";
@import "@fontsource-variable/bricolage-grotesque";
@import "@fontsource-variable/figtree";

@source "./**/*.{ts,tsx}";

@theme {
  --font-display: "Bricolage Grotesque Variable", ui-sans-serif, system-ui, sans-serif;
  --font-sans: "Figtree Variable", ui-sans-serif, system-ui, sans-serif;

  --color-canvas: oklch(0.1 0 0);
  --color-panel: oklch(0.16 0 0);
  --color-ink: oklch(0.97 0.008 100);
  --color-mute: oklch(0.74 0.025 160);
  --color-moss: oklch(0.62 0.12 160);
  --color-ember: oklch(0.7 0.14 50);
  --color-portal: oklch(0.94 0.03 105);
  --color-line: oklch(0.28 0.01 160);

  --ease-out-quart: cubic-bezier(0.25, 1, 0.5, 1);
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
}

:root {
  font-family: var(--font-sans);
  color: var(--color-ink);
  background: var(--color-canvas);
  font-synthesis: none;
  text-rendering: optimizeLegibility;
  color-scheme: dark;
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background: var(--color-canvas);
  overflow-x: clip;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

:focus-visible {
  outline: 2px solid var(--color-moss);
  outline-offset: 3px;
}

.skip-link {
  position: absolute;
  left: 1rem;
  top: -4rem;
  z-index: 80;
  border-radius: 999px;
  background: var(--color-portal);
  color: var(--color-canvas);
  padding: 0.7rem 1.1rem;
  font-size: 0.875rem;
  font-weight: 600;
}

.skip-link:focus {
  top: 1rem;
}

.landing-page {
  background: var(--color-canvas);
  color: var(--color-ink);
}

.font-display {
  font-family: var(--font-display);
}

.text-balance {
  text-wrap: balance;
}

.text-pretty {
  text-wrap: pretty;
}

.portal-frame {
  border: 1px solid color-mix(in oklch, var(--color-portal) 35%, transparent);
  box-shadow: 0 0 0 1px color-mix(in oklch, var(--color-moss) 18%, transparent);
}

.hero-still {
  animation: hero-settle 18s var(--ease-out-quart) both;
}

@keyframes hero-settle {
  from {
    transform: scale(1.08);
  }
  to {
    transform: scale(1);
  }
}

.faq-panel {
  display: grid;
  grid-template-rows: 0fr;
  transition: grid-template-rows 320ms var(--ease-out-quart);
}

.faq-panel[data-open="true"] {
  grid-template-rows: 1fr;
}

.faq-panel > div {
  overflow: hidden;
}

.glow-pulse {
  animation: glow-pulse 4.5s var(--ease-out-quart) infinite alternate;
}

@keyframes glow-pulse {
  from {
    opacity: 0.45;
  }
  to {
    opacity: 0.9;
  }
}

