import { LandingAppButton } from "./landing-app-button";

const tiers = [
  {
    name: "Free",
    id: "tier-free",
    price: "$0",
    cadence: "forever",
    description: "Enough to feel the habit: save, then ask.",
    features: ["20 bookmarks", "Chrome extension", "Ask your library"],
    cta: "Start free",
    featured: false,
  },
  {
    name: "Pro",
    id: "tier-pro",
