node <<'NODE'
const WS = 'ws://127.0.0.1:9337/devtools/page/F0BFC8B4C575FFDAF3167D56BEAF06CB';
const PAGE = 'http://127.0.0.1:9307/';
const OUT = '/tmp/saveit-landing-shots';
const fs = await import('fs');

let id = 0;
const pending = new Map();
const logs = [];
const ws = new WebSocket(WS);

function send(method, params = {}) {
  const n = ++id;
  return new Promise((resolve, reject) => {
    pending.set(n, { resolve, reject });
    ws.send(JSON.stringify({ id: n, method, params }));
    setTimeout(() => {
      if (pending.has(n)) {
        pending.delete(n);
        reject(new Error('timeout ' + method));
      }
    }, 30000);
  });
}

ws.addEventListener('message', (ev) => {
  const msg = JSON.parse(ev.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve, reject } = pending.get(msg.id);
    pending.delete(msg.id);
    if (msg.error) reject(new Error(JSON.stringify(msg.error)));
    else resolve(msg.result);
  }
  if (msg.method === 'Runtime.consoleAPICalled') {
    const args = (msg.params.args || []).map(a => a.value ?? a.description ?? a.type).join(' ');
    logs.push(['console', msg.params.type, args]);
  }
  if (msg.method === 'Runtime.exceptionThrown') {
    logs.push(['exception', msg.params.exceptionDetails?.text, msg.params.exceptionDetails?.exception?.description]);
  }
});

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

async function shot(name) {
  const shot = await send('Page.captureScreenshot', { format: 'png', fromSurface: true });
  fs.writeFileSync(`${OUT}/${name}.png`, Buffer.from(shot.data, 'base64'));
  console.log('SHOT', name, fs.statSync(`${OUT}/${name}.png`).size);
}

ws.addEventListener('open', async () => {
  try {
    await send('Runtime.enable');
    await send('Page.enable');
    await send('Emulation.setDeviceMetricsOverride', { width: 1440, height: 900, deviceScaleFactor: 1, mobile: false });
    await send('Page.navigate', { url: PAGE });
    await send('Page.loadEventFired').catch(() => {});
    await sleep(2500);

    const evalRes = await send('Runtime.evaluate', {
      expression: `({
        title: document.title,
        h1: document.querySelector('h1')?.textContent,
        sections: [...document.querySelectorAll('section')].map(s => s.id || s.querySelector('h2')?.textContent?.slice(0,40)),
        overflowX: document.documentElement.scrollWidth > document.documentElement.clientWidth,
        scrollH: document.documentElement.scrollHeight
      })`,
      returnByValue: true
    });
    console.log('EVAL', JSON.stringify(evalRes.result?.value, null, 2));

    await shot('v-hero');

    for (const sel of ['#workflow', '#promise', '#ios', '#pricing', '#faq']) {
      await send('Runtime.evaluate', {
        expression: `document.querySelector('${sel}')?.scrollIntoView({block:'start', behavior:'instant'})`,
      });
      await sleep(600);
      await shot('v-' + sel.slice(1));
    }

    // click first FAQ
    await send('Runtime.evaluate', {
      expression: `document.querySelector('#faq button')?.click()`,
    });
    await sleep(400);
    await shot('v-faq-open');

    // mobile
    await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
    await send('Runtime.evaluate', { expression: `window.scrollTo(0,0)` });
    await sleep(800);
    await shot('v-mobile-hero');
    await send('Runtime.evaluate', { expression: `document.querySelector('#workflow')?.scrollIntoView({block:'start', behavior:'instant'})` });
    await sleep(500);
    await shot('v-mobile-workflow');
    await send('Runtime.evaluate', { expression: `document.querySelector('#promise')?.scrollIntoView({block:'start', behavior:'instant'})` });
    await sleep(500);
    await shot('v-mobile-promise');
    await send('Runtime.evaluate', { expression: `document.querySelector('#ios')?.scrollIntoView({block:'start', behavior:'instant'})` });
    await sleep(500);
    await shot('v-mobile-ios');
    await send('Runtime.evaluate', { expression: `document.querySelector('#pricing')?.scrollIntoView({block:'start', behavior:'instant'})` });
    await sleep(500);
    await shot('v-mobile-pricing');

    console.log('LOGS', JSON.stringify(logs, null, 2));
    process.exit(0);
  } catch (e) {
    console.error('FAIL', e);
    console.log('LOGS', JSON.stringify(logs, null, 2));
    process.exit(1);
  }
});
ws.addEventListener('error', (e) => { console.error('ws error', e); process.exit(1); });
